import numpy as np
import jax

# Try to import plgpu (pallas gpu utilities)
try:
    from jax.experimental.pallas import gpu as plgpu
except ImportError:
    try:
        from jax._src.pallas import gpu as plgpu
    except ImportError:
        plgpu = None

# Test data
test_array = np.array([-2, -1, 0, 1], np.float32)

# Test atomic_max
try:
    if plgpu is not None and hasattr(plgpu, 'atomic_max'):
        result_max = plgpu.atomic_max(test_array)
        probe("max_f32", result_max)
    else:
        probe_exception("max_f32", Exception("plgpu.atomic_max not available"))
except Exception as e:
    probe_exception("max_f32", e)

# Test atomic_min
try:
    if plgpu is not None and hasattr(plgpu, 'atomic_min'):
        result_min = plgpu.atomic_min(test_array)
        probe("min_f32", result_min)
    else:
        probe_exception("min_f32", Exception("plgpu.atomic_min not available"))
except Exception as e:
    probe_exception("min_f32", e)

